SELECT (SELECT spec FROM episode_art_jobs WHERE id=art_job),batch,position,reference_sha,attempt,slot,round,stage,focus,reason FROM media_candidates WHERE stage NOT IN ('passed','held','failed') ORDER BY (SELECT priority FROM episode_policies pol JOIN episode_art_jobs art ON art.world_slug=pol.world_slug WHERE art.id=media_candidates.art_job) DESC NULLS LAST,(position-1)%3,slot LIMIT 3
